  k  tile=marb_11 object=lamp_h
  l  tile=marb_10 npc=guardia id=guide face=SW script=guide
  m  tile=marb_01 object=vflag
  n  tile=marb_11 object=vflag
  o  tile=marb_01 object=lstatue
  p  tile=marb_00 object=lamp_h
  q  tile=marb_10 npc=vecino_m id=tourist face=NW script=tourist
  R  tile=marb_00                            # D1 (contract 68): the passage in the back wall (a warp to the Ruinas del Origen) behind the sealed slab
  S  tile=marb_01 npc=seal id=seal face=S solid=yes gate=yes script=seal_door hide_flag=ruins_open   # D1: the sealed slab, gone for good once the eight fragments opened it
  r  tile=marb_10 object=lamp_h
  s  tile=marb_01 object=pillar
  t  tile=marb_11 object=fence_j
  u  tile=marb_01 object=fence_j
  v  tile=marb_01 
  w  tile=marb_11 
