@warp v -> senda_3 spawn=north
@warp w -> senda_3 spawn=north
@warp h -> liga_lobby spawn=door
@warp R -> ruinas_origen spawn=in
@script guide npc
    npc_face_hero guide
    say ms.guide
@end
# D1 (contract 68): the sealed gate (an old carved slab in the back wall, eight sockets): it opens when the player holds all eight Origin Fragments (the story flags frag_1 .. frag_8: the bag's count is only a display).
@script seal_door npc
    say ms.seal
    jnf frag_1 no
    jnf frag_2 no
    jnf frag_3 no
    jnf frag_4 no
    jnf frag_5 no
    jnf frag_6 no
    jnf frag_7 no
    jnf frag_8 no
    sfx door
    say ms.seal.open
    setf ruins_open
    end
  no:
    say ms.seal.no
@end
# D1: the tourist's second piece of gossip: the hidden cave of the Piedra Eclipse (a clue; the first line is the old one).
@script tourist npc
    npc_face_hero tourist
    say ms.tourist
    say d1.hint.ms
@end
